-- Synthetic fixtures only. Run with Supabase pgTAP or pg_prove on a disposable DB.
begin;
set local search_path=public,extensions;
select no_plan();
insert into public.contacts(id,user_id,name) values
 ('71000000-0000-0000-0000-000000000001','72000000-0000-0000-0000-000000000001','Synthetic source'),
 ('71000000-0000-0000-0000-000000000002','72000000-0000-0000-0000-000000000001','Synthetic target'),
 ('71000000-0000-0000-0000-000000000003','72000000-0000-0000-0000-000000000002','Synthetic other owner');
create temporary table topic_results(name text primary key, result jsonb);
grant all on topic_results to authenticated;
select set_config('request.jwt.claim.sub','72000000-0000-0000-0000-000000000001',true);
set local role authenticated;
insert into topic_results values('one',public.apply_contact_topic_command('73000000-0000-0000-0000-000000000001',
 '{"action":"create","contact_id":"71000000-0000-0000-0000-000000000001","title":"  Ask about pottery  "}'));
select is((select result#>>'{topic,title}' from topic_results where name='one'),'Ask about pottery','create trims title');
select is((select result#>>'{topic,priority}' from topic_results where name='one'),'normal','default normal priority');
select is((select result#>>'{topic,mode}' from topic_results where name='one'),'one_off','default one off');
select is(public.apply_contact_topic_command('73000000-0000-0000-0000-000000000001',
 '{"action":"create","contact_id":"71000000-0000-0000-0000-000000000001","title":"  Ask about pottery  "}')->>'replayed','true','same request replays');
select is((select count(*)::integer from public.contact_topic_events where request_id='73000000-0000-0000-0000-000000000001'),1,'retry appends one event only');
select throws_ok($$select public.apply_contact_topic_command('73000000-0000-0000-0000-000000000001','{"action":"create","title":"Different"}')$$,'22023','Request ID already used for a different command','payload conflict');
select throws_ok($$select public.apply_contact_topic_command(gen_random_uuid(),'{"action":"create","contact_id":"71000000-0000-0000-0000-000000000003","title":"Wrong owner"}')$$,'42501','Person not found or already merged','cannot create for another owner');
select throws_ok($$insert into public.contact_topics(user_id,contact_id,title) values('72000000-0000-0000-0000-000000000001','71000000-0000-0000-0000-000000000001','Bypass')$$,'42501',null,'browser cannot bypass transitions');
select throws_ok($$delete from public.contact_topic_events$$,'42501',null,'browser cannot erase history');
select throws_ok($$select public.apply_contact_topic_command_for_user('72000000-0000-0000-0000-000000000001',gen_random_uuid(),'{}')$$,'42501',null,'browser cannot supply owner to service wrapper');
select throws_ok($$select public.apply_contact_topic_command_internal('72000000-0000-0000-0000-000000000001',gen_random_uuid(),'{}')$$,'42501',null,'browser cannot call internal helper');
insert into topic_results select 'done',public.apply_contact_topic_command(gen_random_uuid(),jsonb_build_object('action','discuss','topic_id',result#>>'{topic,id}','expected_version',1,'discussed_at','2020-01-01T10:00:00+01:00')) from topic_results where name='one';
select is((select result#>>'{topic,status}' from topic_results where name='done'),'completed','one off completes');
select throws_ok($$select public.apply_contact_topic_command(gen_random_uuid(),jsonb_build_object('action','archive','topic_id',result#>>'{topic,id}','expected_version',1)) from topic_results where name='one'$$,'PT409','Topic version conflict','stale update refused');
insert into topic_results select 'undo',public.apply_contact_topic_command(gen_random_uuid(),jsonb_build_object('action','undo','topic_id',result#>>'{topic,id}','expected_version',2,'event_id',result->>'event_id')) from topic_results where name='done';
select is((select result#>>'{topic,status}' from topic_results where name='undo'),'active','undo restores active');
select ok((select result#>>'{topic,last_discussed_at}' is null from topic_results where name='undo'),'undo removes last discussed time');
select is((select count(*)::integer from public.contact_topic_events where action='discuss'),1,'undo retains discussion audit');
select throws_ok($$select public.apply_contact_topic_command(gen_random_uuid(),jsonb_build_object('action','undo','topic_id',result#>>'{topic,id}','expected_version',3,'event_id',result->>'event_id')) from topic_results where name='done'$$,'PT409','Only the latest unreversed change can be undone','cannot undo already reversed event');
insert into topic_results select 'edited',public.apply_contact_topic_command(gen_random_uuid(),jsonb_build_object('action','update','topic_id',result#>>'{topic,id}','expected_version',3,'patch',jsonb_build_object('title','New wording'))) from topic_results where name='one';
select is((select after_state->>'title' from public.contact_topic_events where action='discuss'),'Ask about pottery','old discussion wording is immutable');
insert into topic_results values('repeat',public.apply_contact_topic_command(gen_random_uuid(),'{"action":"create","contact_id":"71000000-0000-0000-0000-000000000001","title":"Weekly craft news","mode":"recurring","priority":"high"}'));
insert into topic_results select 'repeat1',public.apply_contact_topic_command(gen_random_uuid(),jsonb_build_object('action','discuss','topic_id',result#>>'{topic,id}','expected_version',1,'discussed_at','2020-02-01T10:00:00Z')) from topic_results where name='repeat';
select is((select result#>>'{topic,status}' from topic_results where name='repeat1'),'active','recurring remains active');
insert into topic_results select 'repeat2',public.apply_contact_topic_command(gen_random_uuid(),jsonb_build_object('action','discuss','topic_id',result#>>'{topic,id}','expected_version',2,'discussed_at','2020-02-02T10:00:00Z','close_after',true)) from topic_results where name='repeat';
select is((select result#>>'{topic,status}' from topic_results where name='repeat2'),'completed','close after completes recurring');
insert into topic_results select 'reopened',public.apply_contact_topic_command(gen_random_uuid(),jsonb_build_object('action','reopen','topic_id',result#>>'{topic,id}','expected_version',3)) from topic_results where name='repeat';
select is((select result#>>'{topic,status}' from topic_results where name='reopened'),'active','reopen restores agenda');
insert into topic_results select 'archived',public.apply_contact_topic_command(gen_random_uuid(),jsonb_build_object('action','archive','topic_id',result#>>'{topic,id}','expected_version',4)) from topic_results where name='repeat';
select is((select result#>>'{topic,status}' from topic_results where name='archived'),'archived','archive distinct from completed');
select is((select count(*)::integer from public.contact_topic_events where action='discuss'),3,'archive and reopen add no discussion');
select throws_ok($$select public.apply_contact_topic_command(gen_random_uuid(),jsonb_build_object('action','discuss','topic_id',result#>>'{topic,id}','expected_version',4,'discussed_at','2999-01-01T00:00:00Z')) from topic_results where name='one'$$,'22023','Discussion time cannot be in the future','future dates rejected');
select throws_ok($$select public.apply_contact_topic_command(gen_random_uuid(),jsonb_build_object('action','discuss','topic_id',result#>>'{topic,id}','expected_version',4,'discussed_at','2020-01-01')) from topic_results where name='one'$$,'22023','Discussion time requires an explicit timezone','bare dates require caller local timezone conversion');
select throws_ok($$select public.apply_contact_topic_command(gen_random_uuid(),'{"action":"create","contact_id":"71000000-0000-0000-0000-000000000001","title":"x","user_id":"spoof"}')$$,'22023','Unsupported command keys or action','extra keys rejected');
select throws_ok($$select public.apply_contact_topic_command(gen_random_uuid(),'{"action":"create","contact_id":"71000000-0000-0000-0000-000000000001","title":" "}')$$,'23514',null,'empty title rejected');
select throws_ok($$select public.apply_contact_topic_command(gen_random_uuid(),'{"action":"create","contact_id":"71000000-0000-0000-0000-000000000001","title":"x","priority":"urgent"}')$$,'23514',null,'invalid priority rejected');
select set_config('request.jwt.claim.sub','72000000-0000-0000-0000-000000000002',true);
select is((select count(*)::integer from public.contact_topics),0,'other owner cannot select topics');
select is((select count(*)::integer from public.contact_topic_events),0,'other owner cannot select history');
select throws_ok($$select public.apply_contact_topic_command(gen_random_uuid(),jsonb_build_object('action','archive','topic_id',result#>>'{topic,id}','expected_version',4)) from topic_results where name='one'$$,'42501','Topic not found','direct ID ownership enforced');
select set_config('request.jwt.claim.sub','72000000-0000-0000-0000-000000000001',true);
select throws_ok($$update public.contacts set merged_into=id where id='71000000-0000-0000-0000-000000000001'$$,'22023','Reassign this person''s conversation topics to another person before merging into yourself','self merge refuses topics');
select is((select count(*)::integer from public.contact_topics where contact_id='71000000-0000-0000-0000-000000000001'),2,'failed merge retains topics');
select lives_ok($$update public.contacts set merged_into='71000000-0000-0000-0000-000000000002' where id='71000000-0000-0000-0000-000000000001'$$,'person merge transfers at marker');
select is((select count(*)::integer from public.contact_topics where contact_id='71000000-0000-0000-0000-000000000002'),2,'all statuses transfer');
select is((select count(*)::integer from public.contact_topic_events where action='discuss'),3,'merge retains every occurrence');
select is((select priority from public.contact_topics where id=(select (result#>>'{topic,id}')::uuid from topic_results where name='repeat')),'high','merge retains priority');
select throws_ok($$select public.apply_contact_topic_command(gen_random_uuid(),'{"action":"create","contact_id":"71000000-0000-0000-0000-000000000001","title":"Too late"}')$$,'42501','Person not found or already merged','merged source rejects new topics');
select lives_ok($$delete from public.contacts where id='71000000-0000-0000-0000-000000000002'$$,'explicit person deletion cascades');
select is((select count(*)::integer from public.contact_topics),0,'deleted person topics gone');
select is((select count(*)::integer from public.contact_topic_events),0,'deleted person events gone');
reset role;
select throws_ok($$insert into public.contact_topics(user_id,contact_id,title) values('72000000-0000-0000-0000-000000000001','71000000-0000-0000-0000-000000000003','Mismatched owner')$$,'23503',null,'composite FK rejects mismatched owner even for direct SQL');
select set_config('request.jwt.claim.sub','72000000-0000-0000-0000-000000000001',true);
set local role authenticated;
insert into public.contacts(id,user_id,name) values('71000000-0000-0000-0000-000000000004','72000000-0000-0000-0000-000000000001','Synthetic reassignment target');
insert into topic_results values('transfer',public.apply_contact_topic_command(gen_random_uuid(),'{"action":"create","contact_id":"71000000-0000-0000-0000-000000000001","title":"Synthetic repeat words"}'));
select is(public.reassign_contact_topics('71000000-0000-0000-0000-000000000001','71000000-0000-0000-0000-000000000004'),1,'explicit reassignment moves all topics');
select is((select version from public.contact_topics where id=(select (result#>>'{topic,id}')::uuid from topic_results where name='transfer')),2,'transfer increments version');
select lives_ok($$update public.contacts set merged_into=id where id='71000000-0000-0000-0000-000000000001'$$,'self merge succeeds after explicit topic reassignment');
select is((select count(*)::integer from public.contact_topic_events),2,'reassignment preserves original audit and appends transfer');
reset role;
insert into public.contacts(id,user_id,name) values('71000000-0000-0000-0000-000000000005','72000000-0000-0000-0000-000000000001','Synthetic resumable self merge');
update public.contacts set topic_self_merge_pending=true where id='71000000-0000-0000-0000-000000000005';
select ok((select merged_into is null from public.contacts where id='71000000-0000-0000-0000-000000000005'),'unfinished self merge keeps source visible');
select throws_ok($$select public.apply_contact_topic_command_for_user('72000000-0000-0000-0000-000000000001',gen_random_uuid(),'{"action":"create","contact_id":"71000000-0000-0000-0000-000000000005","title":"During reservation"}')$$,'42501',null,'self reservation rejects concurrent capture');
select lives_ok($$update public.contacts set topic_self_merge_pending=true where id='71000000-0000-0000-0000-000000000005'$$,'same self merge can resume reservation after interruption');
update public.contacts set topic_self_merge_pending=false where id='71000000-0000-0000-0000-000000000005';
select lives_ok($$select public.apply_contact_topic_command_for_user('72000000-0000-0000-0000-000000000001',gen_random_uuid(),'{"action":"create","contact_id":"71000000-0000-0000-0000-000000000005","title":"After recovery"}')$$,'cleared reservation permits capture');
select throws_ok($$update public.contacts set topic_self_merge_pending=true where id='71000000-0000-0000-0000-000000000005'$$,'22023',null,'late topic prevents reservation before profile writes');
select * from finish();
rollback;
